291	    // Count emotion shifts
292	    let emotionShifts = 0;
293	    for (let i = 1; i < journey.length; i++) {
294	      if (journey[i].emotion !== journey[i - 1].emotion) {
295	        emotionShifts++;
296	      }
297	    }
298	
299	    // Calculate escalation risk
300	    const negativeEmotions = ['anger', 'frustration', 'fear', 'sadness'];
301	    const negativeCount = journey.filter(j => negativeEmotions.includes(j.emotion)).length;
302	    const escalationRisk = journey.length > 0 ? negativeCount / journey.length : 0;
303	
304	    // Calculate resolution score
305	    const lastEmotions = journey.slice(-3);
306	    const positiveEmotions = ['joy', 'satisfaction', 'trust', 'relief'];
307	    const positiveCount = lastEmotions.filter(j => positiveEmotions.includes(j.emotion)).length;
308	    const resolutionScore = lastEmotions.length > 0 ? positiveCount / lastEmotions.length : 0.5;
309	
310	    return {
311	      duration,
312	      messageCount: conversation.messages.length,
313	      emotionShifts,
314	      escalationRisk,
315	      resolutionScore
