338	    }
339	
340	    const peaks = keyMoments.filter(m => m.type === 'emotion_peak' && m.impact > 0.8);
341	    if (peaks.length > 2) {
342	      recommendations.push('Multiple emotional peaks - consider de-escalation training');
343	    }
344	
345	    if (recommendations.length === 0) {
346	      recommendations.push('Conversation handled well - use as training example');
347	    }
348	
