/**
 * Conversation Replay Engine Module
 * Allows replaying and analyzing historical conversations
 */

export interface ReplayMessage {
  id: string;
  content: string;
  sender: string;
  timestamp: Date;
  emotions?: Record<string, number>;
  metadata?: Record<string, unknown>;
}

export interface ReplayConversation {
  id: string;
  messages: ReplayMessage[];
  participants: string[];
  startTime: Date;
  endTime: Date;
  outcome?: string;
  tags: string[];
}

export interface ReplayEvent {
  timestamp: Date;
  type: 'message' | 'emotion_shift' | 'intervention' | 'escalation' | 'resolution';
  data: Record<string, unknown>;
  annotation?: string;
}

export interface ReplayAnalysis {
  conversation: ReplayConversation;
  timeline: ReplayEvent[];
  emotionalJourney: Array<{
    timestamp: Date;
    participant: string;
    emotion: string;
    intensity: number;
  }>;
  keyMoments: Array<{
    timestamp: Date;
    type: string;
    description: string;
    impact: number;
  }>;
  metrics: {
    duration: number;
    messageCount: number;
    emotionShifts: number;
    escalationRisk: number;
    resolutionScore: number;
  };
  recommendations: string[];
}

export interface ReplayOptions {
  speed: number; // 1 = real-time, 2 = 2x speed, etc.
  includeAnnotations: boolean;
  highlightEmotions: boolean;
  pauseOnKeyMoments: boolean;
}

export class ConversationReplayEngine {
  private conversations: Map<string, ReplayConversation> = new Map();
  private currentReplay: {
    conversation: ReplayConversation;
    currentIndex: number;
    isPlaying: boolean;
    speed: number;
  } | null = null;

  /**
   * Load a conversation for replay
   */
  loadConversation(conversation: ReplayConversation): void {
    this.conversations.set(conversation.id, conversation);
  }

  /**
   * Start replay of a conversation
   */
  startReplay(conversationId: string, options: Partial<ReplayOptions> = {}): boolean {
    const conversation = this.conversations.get(conversationId);
    if (!conversation) return false;

    this.currentReplay = {
      conversation,
      currentIndex: 0,
      isPlaying: true,
      speed: options.speed || 1
    };

    return true;
  }

  /**
   * Get next message in replay
   */
  getNextMessage(): ReplayMessage | null {
    if (!this.currentReplay || !this.currentReplay.isPlaying) return null;
    if (this.currentReplay.currentIndex >= this.currentReplay.conversation.messages.length) {
      this.currentReplay.isPlaying = false;
      return null;
    }

    const message = this.currentReplay.conversation.messages[this.currentReplay.currentIndex];
    this.currentReplay.currentIndex++;
    return message;
  }

  /**
   * Pause replay
   */
  pauseReplay(): void {
    if (this.currentReplay) {
      this.currentReplay.isPlaying = false;
    }
  }

  /**
   * Resume replay
   */
  resumeReplay(): void {
    if (this.currentReplay) {
      this.currentReplay.isPlaying = true;
    }
  }

  /**
   * Seek to specific point in conversation
   */
  seekTo(index: number): boolean {
    if (!this.currentReplay) return false;
    if (index < 0 || index >= this.currentReplay.conversation.messages.length) return false;

    this.currentReplay.currentIndex = index;
    return true;
  }

  /**
   * Analyze a conversation
   */
  analyzeConversation(conversationId: string): ReplayAnalysis | null {
    const conversation = this.conversations.get(conversationId);
    if (!conversation) return null;

    const timeline = this.buildTimeline(conversation);
    const emotionalJourney = this.buildEmotionalJourney(conversation);
    const keyMoments = this.identifyKeyMoments(conversation, emotionalJourney);
    const metrics = this.calculateMetrics(conversation, emotionalJourney);
    const recommendations = this.generateRecommendations(metrics, keyMoments);

    return {
      conversation,
      timeline,
      emotionalJourney,
      keyMoments,
      metrics,
      recommendations
    };
  }

  /**
   * Build timeline of events
   */
  private buildTimeline(conversation: ReplayConversation): ReplayEvent[] {
    const events: ReplayEvent[] = [];

    for (const message of conversation.messages) {
      events.push({
        timestamp: message.timestamp,
        type: 'message',
        data: {
          sender: message.sender,
          content: message.content.substring(0, 100),
          emotions: message.emotions
        }
      });

      // Check for emotion shifts
      if (message.emotions) {
        const dominantEmotion = Object.entries(message.emotions)
          .sort((a, b) => b[1] - a[1])[0];

        if (dominantEmotion && dominantEmotion[1] > 0.7) {
          events.push({
            timestamp: message.timestamp,
            type: 'emotion_shift',
            data: {
              emotion: dominantEmotion[0],
              intensity: dominantEmotion[1]
            }
          });
        }
      }
    }

    return events.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
  }

  /**
   * Build emotional journey
   */
  private buildEmotionalJourney(conversation: ReplayConversation): ReplayAnalysis['emotionalJourney'] {
    const journey: ReplayAnalysis['emotionalJourney'] = [];

    for (const message of conversation.messages) {
      if (message.emotions) {
        const dominantEntry = Object.entries(message.emotions)
          .sort((a, b) => b[1] - a[1])[0];

        if (dominantEntry) {
          journey.push({
            timestamp: message.timestamp,
            participant: message.sender,
            emotion: dominantEntry[0],
            intensity: dominantEntry[1]
          });
        }
      }
    }

    return journey;
  }

  /**
   * Identify key moments
   */
  private identifyKeyMoments(
    conversation: ReplayConversation,
    journey: ReplayAnalysis['emotionalJourney']
  ): ReplayAnalysis['keyMoments'] {
    const moments: ReplayAnalysis['keyMoments'] = [];

    // Find emotion peaks
    for (let i = 1; i < journey.length - 1; i++) {
      const prev = journey[i - 1];
      const curr = journey[i];
      const next = journey[i + 1];

      // Detect peaks
      if (curr.intensity > prev.intensity && curr.intensity > next.intensity && curr.intensity > 0.7) {
        moments.push({
          timestamp: curr.timestamp,
          type: 'emotion_peak',
          description: `Peak ${curr.emotion} detected from ${curr.participant}`,
          impact: curr.intensity
        });
      }

      // Detect sudden shifts
      if (Math.abs(curr.intensity - prev.intensity) > 0.4) {
        moments.push({
          timestamp: curr.timestamp,
          type: 'emotion_shift',
          description: `Sudden shift from ${prev.emotion} to ${curr.emotion}`,
          impact: Math.abs(curr.intensity - prev.intensity)
        });
      }
    }

    // Find resolution point if outcome is positive
    if (conversation.outcome === 'resolved') {
      const lastPositive = journey.filter(j => 
        ['joy', 'satisfaction', 'relief', 'trust'].includes(j.emotion)
      ).pop();

      if (lastPositive) {
        moments.push({
          timestamp: lastPositive.timestamp,
          type: 'resolution',
          description: 'Conversation reached positive resolution',
          impact: 0.9
        });
      }
    }

    return moments.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
  }

  /**
   * Calculate metrics
   */
  private calculateMetrics(
    conversation: ReplayConversation,
    journey: ReplayAnalysis['emotionalJourney']
  ): ReplayAnalysis['metrics'] {
    const duration = conversation.endTime.getTime() - conversation.startTime.getTime();

    // Count emotion shifts
    let emotionShifts = 0;
    for (let i = 1; i < journey.length; i++) {
      if (journey[i].emotion !== journey[i - 1].emotion) {
        emotionShifts++;
      }
    }

    // Calculate escalation risk
    const negativeEmotions = ['anger', 'frustration', 'fear', 'sadness'];
    const negativeCount = journey.filter(j => negativeEmotions.includes(j.emotion)).length;
    const escalationRisk = journey.length > 0 ? negativeCount / journey.length : 0;

    // Calculate resolution score
    const lastEmotions = journey.slice(-3);
    const positiveEmotions = ['joy', 'satisfaction', 'trust', 'relief'];
    const positiveCount = lastEmotions.filter(j => positiveEmotions.includes(j.emotion)).length;
    const resolutionScore = lastEmotions.length > 0 ? positiveCount / lastEmotions.length : 0.5;

    return {
      duration,
      messageCount: conversation.messages.length,
      emotionShifts,
      escalationRisk,
      resolutionScore
    };
  }

  /**
   * Generate recommendations
   */
  private generateRecommendations(
    metrics: ReplayAnalysis['metrics'],
    keyMoments: ReplayAnalysis['keyMoments']
  ): string[] {
    const recommendations: string[] = [];

    if (metrics.escalationRisk > 0.5) {
      recommendations.push('High escalation risk detected - consider earlier intervention');
    }

    if (metrics.emotionShifts > 5) {
      recommendations.push('High emotional volatility - more consistent tone may help');
    }

    if (metrics.resolutionScore < 0.5) {
      recommendations.push('Low resolution score - review closing techniques');
    }

    const peaks = keyMoments.filter(m => m.type === 'emotion_peak' && m.impact > 0.8);
    if (peaks.length > 2) {
      recommendations.push('Multiple emotional peaks - consider de-escalation training');
    }

    if (recommendations.length === 0) {
      recommendations.push('Conversation handled well - use as training example');
    }

    return recommendations;
  }

  /**
   * Export conversation for sharing
   */
  exportConversation(conversationId: string, format: 'json' | 'transcript' = 'json'): string | null {
    const conversation = this.conversations.get(conversationId);
    if (!conversation) return null;

    if (format === 'transcript') {
      return conversation.messages
        .map(m => `[${m.timestamp.toISOString()}] ${m.sender}: ${m.content}`)
        .join('\n');
    }

    return JSON.stringify(conversation, null, 2);
  }

  /**
   * Get replay status
   */
  getReplayStatus(): { isPlaying: boolean; progress: number } | null {
    if (!this.currentReplay) return null;

    return {
      isPlaying: this.currentReplay.isPlaying,
      progress: this.currentReplay.currentIndex / this.currentReplay.conversation.messages.length
    };
  }

  /**
   * Stop replay
   */
  stopReplay(): void {
    this.currentReplay = null;
  }
}

export default ConversationReplayEngine;

