import { router } from '../_core/trpc';
import { governedPublicProcedure as publicProcedure } from '../governance/trpc-enforcement';
import { z } from 'zod';
import { ConversationReplayEngine, ReplayOptions } from './engine';
import { unsafeCast } from '../../shared/type-bridge';

const replayEngine = new ConversationReplayEngine();

export const replayRouter = router({
  loadConversation: publicProcedure
    .input(z.object({
      id: z.string(),
      participants: z.array(z.string()),
      startTime: z.date(),
      endTime: z.date(),
      outcome: z.string().optional(),
      tags: z.array(z.string()),
      messages: z.array(z.object({
        id: z.string(),
        content: z.string(),
        sender: z.string(),
        timestamp: z.date(),
        emotions: z.record(z.string(), z.number()).optional(),
        metadata: z.record(z.string(), z.unknown()).optional()
      }))
    }))
    .mutation(({ input }) => {
      try {
        replayEngine.loadConversation(unsafeCast(input, "boundary cast"));
        return {
          success: true,
          data: { conversationId: input.id },
          error: null
        };
      } catch (error) {
        return {
          success: false,
          data: null,
          error: error instanceof Error ? error.message : 'Failed to load conversation'
        };
      }
    }),

  startReplay: publicProcedure
    .input(z.object({
      conversationId: z.string(),
      options: z.object({
        speed: z.number().default(1),
        includeAnnotations: z.boolean().default(true),
        highlightEmotions: z.boolean().default(true),
        pauseOnKeyMoments: z.boolean().default(false)
      }).partial().optional()
    }))
    .mutation(({ input }) => {
      try {
        const started = replayEngine.startReplay(input.conversationId, input.options as Partial<ReplayOptions>);
        return {
          success: started,
          data: { isPlaying: started },
          error: started ? null : 'Failed to start replay'
        };
      } catch (error) {
        return {
          success: false,
          data: null,
          error: error instanceof Error ? error.message : 'Replay error'
        };
      }
    }),

  getAnalysis: publicProcedure
    .input(z.object({
      conversationId: z.string()
    }))
    .query(({ input }) => {
      try {
        const analysis = (replayEngine as unknown as Record<string, unknown>).analyzeConversation?.(input.conversationId);
        return {
          success: true,
          data: analysis || null,
          error: null
        };
      } catch (error) {
        return {
          success: false,
          data: null,
          error: error instanceof Error ? error.message : 'Analysis failed'
        };
      }
    })
});

